rules.prefer:
SELECT id, email, name FROM customers WHERE id = $1;

INSERT INTO customers (email, name) VALUES ($1, $2)
RETURNING id;

rules.avoid:
SELECT id, status FROM orders
WHERE customer_id = $1
LIMIT 1;

SELECT c.id FROM customers c
WHERE c.id NOT IN (SELECT o.customer_id FROM orders o);
-- returns nothing as soon as one orders.customer_id is NULL

rules.prefer:
SELECT c.id FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id = c.id
);

rules.avoid:
SELECT id FROM orders
WHERE created_at::date = DATE '2026-11-15';

SELECT id FROM customers WHERE lower(email) = $1;

rules.prefer:
SELECT id FROM orders
WHERE created_at >= '2026-11-15' AND created_at < '2026-11-16';

-- or index the expression the query uses
CREATE INDEX customers_email_lower_idx ON customers (lower(email));

SELECT count(*) FROM orders
WHERE created_at >= '2026-11-15'
  AND created_at <  '2026-11-16';

SELECT EXISTS (
  SELECT 1 FROM orders WHERE customer_id = $1
) AS has_orders;

-- planner estimate, refreshed by VACUUM and ANALYZE (-1 = never analyzed)
SELECT reltuples::bigint AS estimate
FROM pg_class WHERE oid = 'public.events'::regclass;

SELECT id FROM users WHERE email = $1;

-- identifiers cannot be parameters: quote them in dynamic SQL
