rules.avoid:
-- executed once per order in an application loop
SELECT id, email FROM customers WHERE id = $1;
INSERT INTO order_items (order_id, sku, qty) VALUES ($1, $2, $3);

rules.prefer:
SELECT id, email FROM customers WHERE id = ANY($1::bigint[]);

INSERT INTO order_items (order_id, sku, qty)
SELECT * FROM unnest($1::bigint[], $2::text[], $3::int[]);

rules.avoid:
CREATE TABLE orders (
  id serial PRIMARY KEY,
  total numeric(12,2) NOT NULL
);

rules.prefer:
CREATE TABLE orders (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  total numeric(12,2) NOT NULL
);

rules.avoid:
CREATE TABLE sessions (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  user_id bigint NOT NULL
);

rules.prefer:
CREATE TABLE sessions (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  user_id bigint NOT NULL
);

rules.avoid:
CREATE TABLE events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  occurred_at timestamp NOT NULL DEFAULT now()
);

rules.prefer:
CREATE TABLE events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  occurred_at timestamptz NOT NULL DEFAULT now()
);

rules.avoid:
CREATE TABLE accounts (
  email varchar(255) NOT NULL,
  country_code char(2) NOT NULL
);

rules.prefer:
CREATE TABLE accounts (
  email text NOT NULL,
  country_code text NOT NULL,
  CONSTRAINT accounts_email_length CHECK (char_length(email) <= 254),
  CONSTRAINT accounts_country_code_format CHECK (country_code ~ '^[A-Z]{2}$')
);

rules.avoid:
CREATE TABLE invoices (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  amount double precision NOT NULL
);

rules.prefer:
CREATE TABLE invoices (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  amount numeric(14,2) NOT NULL,
  currency text NOT NULL
);

rules.avoid:
CREATE TABLE orders (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id bigint,
  status text
);

rules.prefer:
CREATE TABLE orders (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL,
  status text NOT NULL DEFAULT 'new',
  shipped_at timestamptz  -- NULL means "not shipped yet"
);

rules.avoid:
CREATE TABLE order_items (
  order_id bigint NOT NULL,  -- "refers to orders.id"
  sku text NOT NULL
);

rules.prefer:
CREATE TABLE order_items (
  order_id bigint NOT NULL,
  sku text NOT NULL,
  CONSTRAINT order_items_order_id_fkey
    FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE
);

rules.avoid:
CREATE TABLE products (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  data jsonb NOT NULL  -- {"sku": ..., "price": ..., "color": ...}
);

rules.prefer:
CREATE TABLE order_statuses (
  code text PRIMARY KEY,
  is_final boolean NOT NULL DEFAULT false
);
ALTER TABLE orders ADD CONSTRAINT orders_status_fkey
  FOREIGN KEY (status) REFERENCES order_statuses (code);

rules.avoid:
CREATE TABLE readings (
  ok boolean, device_id bigint,
  calibrated boolean, recorded_at timestamptz,
  flagged boolean, value integer
);

rules.prefer:
CREATE TABLE readings (
  device_id bigint, recorded_at timestamptz,  -- 8-byte types first
  value integer,                              -- then 4-byte
  ok boolean, calibrated boolean, flagged boolean
);

