rules.avoid:
BEGIN;  -- READ COMMITTED
SELECT sum(amount) FROM ledger WHERE account_id = $1;
SELECT count(*)    FROM ledger WHERE account_id = $1;  -- may see new rows
COMMIT;

rules.prefer:
BEGIN ISOLATION LEVEL REPEATABLE READ, READ ONLY;
SELECT sum(amount) FROM ledger WHERE account_id = $1;
SELECT count(*)    FROM ledger WHERE account_id = $1;
COMMIT;

BEGIN ISOLATION LEVEL SERIALIZABLE;  -- invariants across rows; retry on 40001
COMMIT;

rules.avoid:
-- session A: transfer from 3 to 7
UPDATE accounts SET balance = balance - 50 WHERE id = 3;
UPDATE accounts SET balance = balance + 50 WHERE id = 7;
-- session B at the same time: transfer from 7 to 3
UPDATE accounts SET balance = balance - 20 WHERE id = 7;
UPDATE accounts SET balance = balance + 20 WHERE id = 3;

rules.prefer:
BEGIN;
SELECT id FROM accounts WHERE id IN (3, 7) ORDER BY id FOR UPDATE;
UPDATE accounts SET balance = balance - 50 WHERE id = 3;
UPDATE accounts SET balance = balance + 50 WHERE id = 7;
COMMIT;

rules.avoid:
SELECT balance FROM accounts WHERE id = $1;     -- 100
-- application computes 100 - 10
UPDATE accounts SET balance = 90 WHERE id = $1;

SELECT 1 FROM customers WHERE email = $1;
